const fs = require('fs');
const path = require('path');
const os = require('os');

// Simulate the app-state file in a temp location
const tmpDir = path.join(os.tmpdir(), 'fanbox-test-' + Date.now());
fs.mkdirSync(tmpDir, { recursive: true });
const stateFile = path.join(tmpDir, 'app-state.json');

// Test 1: loadAppState when no file exists
function loadAppState() {
  try {
    const raw = fs.readFileSync(stateFile, 'utf8');
    const s = JSON.parse(raw);
    if (s && s.version === 1) return s;
  } catch { }
  return { version: 1 };
}

const s1 = loadAppState();
console.log('Test 1 (no file):', JSON.stringify(s1));
console.assert(s1.version === 1 && !s1.cwd, 'Should return default');

// Test 2: saveAppState + loadAppState roundtrip
const testState = {
  version: 1,
  cwd: 'C:/Users/test/project',
  selected: 'C:/Users/test/project/index.js',
  terminal: { open: true, dock: 'right', tabs: [{ cwd: 'C:/Users/test/project', title: 'project' }] },
  chat: { open: false }
};
const tmp = stateFile + '.tmp';
fs.writeFileSync(tmp, JSON.stringify(testState));
fs.renameSync(tmp, stateFile);

const s2 = loadAppState();
console.log('Test 2 (roundtrip): cwd =', s2.cwd, '| tabs =', s2.terminal.tabs.length);
console.assert(s2.cwd === testState.cwd, 'cwd should match');
console.assert(s2.terminal.tabs.length === 1, 'tabs should match');
console.assert(s2.selected === testState.selected, 'selected should match');

// Test 3: corrupted file fallback
fs.writeFileSync(stateFile, 'not json at all');
const s3 = loadAppState();
console.log('Test 3 (corrupted):', JSON.stringify(s3));
console.assert(s3.version === 1 && !s3.cwd, 'Should return default on corrupt');

// Cleanup
fs.rmSync(tmpDir, { recursive: true });
console.log('ALL APP-STATE TESTS PASSED');
"
